def relabel(node: Any) -> Any:
    """Deep-copy a question config, replacing sub-part labels with the official SEBI wording."""
    if isinstance(node, dict):
        return {k: (SEBI_LABELS.get(v, v) if k == 'label' and isinstance(v, str) else relabel(v)) for k, v in node.items()}
    if isinstance(node, list):
        return [relabel(v) for v in node]
    return node
